('p1_dif05_learning',1,'P1DIF05-L01',null,'P1-DIF-05','learning',false),('p1_dif05_learning',2,'P1DIF05-L02',null,'P1-DIF-05','learning',false),('p1_dif05_learning',3,'P1DIF05-L03',null,'P1-DIF-05','learning',false),('p1_dif05_learning',4,null,'P1DIF05-W01','P1-DIF-05','written',false),
('p1_dif06_learning',1,'P1DIF06-L01',null,'P1-DIF-06','learning',false),('p1_dif06_learning',2,'P1DIF06-L02',null,'P1-DIF-06','learning',false),('p1_dif06_learning',3,'P1DIF06-L03',null,'P1-DIF-06','learning',false),('p1_dif06_learning',4,null,'P1DIF06-W01','P1-DIF-06','written',false),
('p1_dif07_learning',1,'P1DIF07-L01',null,'P1-DIF-07','learning',false),('p1_dif07_learning',2,'P1DIF07-L02',null,'P1-DIF-07','learning',false),('p1_dif07_learning',3,'P1DIF07-L03',null,'P1-DIF-07','learning',false),('p1_dif07_learning',4,null,'P1DIF07-W01','P1-DIF-07','written',false),
('p1_dif05_retest',1,'P1DIF05-R01',null,'P1-DIF-05','retest',true),('p1_dif06_retest',1,'P1DIF06-R01',null,'P1-DIF-06','retest',true),('p1_dif07_retest',1,'P1DIF07-R01',null,'P1-DIF-07','retest',true),
('p1_aw21_diff_apps_mixed',1,'P1DIF05-M01',null,'P1-DIF-05','mixed',true),('p1_aw21_diff_apps_mixed',2,'P1DIF06-M01',null,'P1-DIF-06','mixed',true),('p1_aw21_diff_apps_mixed',3,'P1DIF07-M01',null,'P1-DIF-07','mixed',true))
insert into private.exam_prep_assessment_items(assessment_id,item_order,question_id,written_task_id,primary_skill_code,reserve_role,is_holdout) select a.id,i.ord,m.question_id,w.id,i.skill,i.role,i.holdout from items i join a on a.assessment_key=i.akey left join m on m.content_key=i.ckey left join w on w.task_key=i.wkey on conflict(assessment_id,item_order) do nothing;

update private.exam_prep_question_content_meta m set copyright_status='pass',qa_scope_status='pass',qa_math_status='pass',qa_language_status='pass',qa_technical_status='pass',diagnostic_rule_status=case when reserve_role='diagnostic' then 'approved' else 'not_applicable' end,lifecycle_state='approved',approved_at=now(),updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p1_aw21_24_diff_apps_v1' and cv.status='draft';
update private.exam_prep_content_versions set status='approved',approved_at=now() where content_version='p1_aw21_24_diff_apps_v1' and status='draft';
update private.exam_prep_question_content_meta m set lifecycle_state=case when reserve_role='learning' then 'published' else 'reserve' end,exposure_state=case when reserve_role='learning' then 'released' else 'withheld' end,published_at=case when reserve_role='learning' then now() else null end,updated_at=now() from private.exam_prep_content_versions cv where cv.id=m.content_version_id and cv.content_version='p1_aw21_24_diff_apps_v1' and cv.status='approved';
update private.exam_prep_written_tasks w set lifecycle_state='published' from private.exam_prep_content_versions cv where cv.id=w.content_version_id and cv.content_version='p1_aw21_24_diff_apps_v1' and cv.status='approved';
update private.exam_prep_assessments a set status='published',approved_at=coalesce(a.approved_at,now()) from private.exam_prep_content_versions cv where cv.id=a.content_version_id and cv.content_version='p1_aw21_24_diff_apps_v1' and cv.status='approved';
update private.exam_prep_content_versions set status='published',published_at=now() where content_version='p1_aw21_24_diff_apps_v1' and status='approved';

do $$ declare v_program bigint; v_skill text; begin select id into v_program from private.exam_prep_program_versions where program_key='math_as_p1_p5' and version_key='p1_p5_canonical_v1_0'; foreach v_skill in array array['P1-DIF-05','P1-DIF-06','P1-DIF-07'] loop if not private.exam_prep_skill_content_ready_v1(v_program,'P1',v_skill) then raise exception 'P1 differentiation application skill not ready %',v_skill; end if; end loop; if exists(select 1 from public.questions where book_ref like 'ExamPrep:P1:p1_aw21_24_diff_apps_v1:%' and is_active) then raise exception 'P1 differentiation legacy activation residue'; end if; if exists(select 1 from private.exam_prep_feature_config where program_key='math_as_p1_p5' and (rollout_state<>'off' or core_enabled or ai_enabled or mentor_enabled or not kill_switch)) then raise exception 'P1 differentiation publication escaped fail-closed'; end if; if exists(select 1 from private.exam_prep_feature_entitlements where entitlement_status='active') then raise exception 'P1 differentiation active entitlement residue'; end if; end $$;
commit;
